(self.webpackChunkjalaranu_web=self.webpackChunkjalaranu_web||[]).push([[125],{1396:function(a){a.exports={siteMetadata:{siteUrl:"https://jalaranu.org",title:"Jalaranu"},pathPrefix:{}.PATH_PREFIX||"",plugins:[]}},5070:function(a,e,n){"use strict";n.r(e),n.d(e,{Head:function(){return c},default:function(){return m}});var i=n(6540),t=n(7310),s=JSON.parse('{"locale":"en","langLabel":"EN","default":true,"site":{"title":"Jalaranu","tagline":"Underlake datacenter project","description":"Explore Jalaranu\'s underlake datacenter project, validation approach, and partnership opportunities for computing infrastructure in Indonesia.","footerTagline":"Jalaranu - developing an underlake datacenter project to support Indonesia\'s digital resilience. The project evaluates thermal efficiency, operational reliability, and environmental effects through a staged, evidence-led program before any commitment to construction.","copyright":"Jalaranu","logoAlt":"Jalaranu","skipLink":"Skip to main content","menuToggle":"Toggle menu","socialFollow":"Follow Jalaranu","social":{"instagram":"https://instagram.com/projectjalaranu","x":"https://x.com/projectjalaranu","linkedin":"https://www.linkedin.com/company/projectjalaranu","facebook":"https://www.facebook.com/projectjalaranu","tiktok":"https://www.tiktok.com/@projectjalaranu","github":"https://github.com/jalaranu"},"languageSwitch":"Switch language to","languageMenu":"Language","languages":{"en":"English","id":"Bahasa Indonesia"},"carouselPrev":"Previous slide","carouselNext":"Next slide","carouselPause":"Pause slideshow","carouselPlay":"Play slideshow","carouselGoTo":"Go to slide","carouselSlides":"Hero image slides","brandSlogan":"Cold, silent, a sustainable data realm."},"nav":{"technology":"Technology","validation":"Validation","partnerships":"Partnerships","about":"About","primaryCta":"Discuss a Partnership"},"pages":{"home":{"seoTitle":"Jalaranu | Underlake Datacenter Project","seoDescription":"Explore Jalaranu\'s underlake datacenter project, validation approach, and partnership opportunities for computing infrastructure in Indonesia.","hero":{"eyebrow":"Underlake datacenter project","h1":"Computing infrastructure **beneath the lake**. Supporting Indonesia\'s ==digital resilience==.","intro":["Jalaranu is developing a modular underlake datacenter project. The focus is to evaluate **thermal efficiency, operational reliability**, and the feasibility of deployment in Indonesia.","We welcome collaboration with investors, institutions, and technology partners to establish a measurable foundation for development."],"primaryCta":{"label":"Discuss a Partnership","to":"/en/partnerships/#contact"},"secondaryCta":{"label":"Explore the Technology","to":"/en/technology/"},"caption":"Project illustration. Final configuration is subject to study and engineering findings.","imageAlt":"Project illustration: the Jalaranu datacenter module beneath the lake surface, connected to shore-based support facilities by protected power and communication routes.","slides":[{"src":"/assets/hero/danau-batur.webp","alt":"Lake Batur, Bali, seen from its volcanic shore"},{"src":"/assets/hero/danau-matano.webp","alt":"Lake Matano, South Sulawesi, an ancient deep-water lake"}]},"why":{"h2":"Why consider a location **beneath a lake**?","body":["Underwater placement offers a different approach to heat management, physical space, and infrastructure access. Its potential benefits need to be assessed alongside the implications for deployment, maintenance, connectivity, and recovery.","The central question is: under what conditions would this approach be more feasible than a land-based datacenter using water-based cooling?","Jalaranu places that comparison at the centre of its evaluation."],"focuses":[{"title":"Thermal performance","body":"**Assessing heat transfer** and energy demand under defined site conditions and workloads."},{"title":"Operational reliability","body":"**Testing how the system can be monitored, maintained, and recovered** when disruptions occur."},{"title":"Overall feasibility","body":"**Comparing whole-life costs** and responsibilities towards the environment."}],"cta":{"label":"See the Validation Approach","to":"/en/validation/"}},"system":{"h2":"One system, from shore to submerged module.","body":"The Jalaranu project connects shore-based support facilities with a computing module beneath the water. Planning covers power, connectivity, heat management, monitoring, and how the module is deployed and retrieved.","items":[{"title":"Shore facilities","body":"Interfaces for power, networking, and operational management."},{"title":"Shore-to-module connections","body":"Power and communications routes to be designed around service-continuity requirements."},{"title":"Underwater module","body":"A computing enclosure and supporting systems to be evaluated through engineering and testing."},{"title":"Monitoring and recovery","body":"Observation of system conditions, incident response, and module retrieval."}],"cta":{"label":"Understand the Project","to":"/en/technology/#system"}},"validation":{"h2":"Progress assessed through evidence.","body":["Each development stage needs to answer specific questions: does performance meet the requirement, how does the system behave when it fails, what does it cost to operate, and how are environmental effects assessed?","Test plans, measured results, and their limitations provide the basis for decisions about further development."],"cta":{"label":"Explore Validation","to":"/en/validation/"}},"partnerships":{"h2":"Help shape Jalaranu\'s next stage.","tracks":[{"title":"Investors","body":"Explore milestone-based funding and business-model evaluation."},{"title":"Government and defence","body":"Discuss use requirements, evaluation criteria, and potential pilot development."},{"title":"Industry partners","body":"Explore contributions to engineering, energy, networks, manufacturing, and operations."},{"title":"Research partners","body":"Develop test methods and technical, economic, and environmental studies."}],"cta":{"label":"Find Your Partnership Route","to":"/en/partnerships/"}},"closing":{"h2":"What would need to be ==demonstrated for this project to be relevant== to your organisation?","body":"Start with your requirements, the scope of evaluation, and the contribution we could develop together.","cta":{"label":"Discuss a Partnership","to":"/en/partnerships/#contact"}}},"technology":{"seoTitle":"Underlake Datacenter Technology | Jalaranu","seoDescription":"Explore the Jalaranu project: from shore facilities and computing modules to heat management, connectivity, and recovery.","hero":{"h1":"Engineering starts with the right questions.","body":"Jalaranu explores the underlake datacenter as **one complete system**. Module placement needs to be evaluated together with power, networking, heat management, maintenance, and recovery."},"architecture":{"h2":"From shore interfaces to the underwater environment.","body":["The project architecture includes four elements: shore-based support facilities, power and communications connections, the computing module, and monitoring and operational management. Their relationships determine how the overall facility can function and recover.","Early visualisations use a truncated square pyramid. This is a design exploration; final geometry, materials, and specifications will follow engineering and test findings."],"anchor":"system","visualNote":"A block diagram and cross-section showing logical connections, without coordinates or facility-security details.","imageAlt":"Engineering figure of the truncated-pyramid module: front elevation, section A-A, roof framing plan, and watertight joint detail.","imageCaption":"Dimensional engineering draft, not a fabrication drawing."},"engineering":{"h2":"Five areas to evaluate.","items":[{"title":"Heat management","body":"**Water conditions, heat transfer**, computing loads, and the energy required by supporting systems."},{"title":"Module integrity","body":"**The ability of structures, joints, and system interfaces** to withstand the defined operating conditions."},{"title":"Power and connectivity","body":"**Service needs, redundancy options**, behaviour during connection failures, and recovery procedures."},{"title":"Maintenance","body":"**What can be monitored remotely**, when intervention is required, and how the module can be handled or retrieved."},{"title":"Security and control","body":"**Administrative access, event monitoring, key management**, operator responsibilities, and protection of physical and digital interfaces."}]},"comparison":{"h2":"Advantages need to be assessed against relevant alternatives.","body":["Evaluation should compare the underlake project with land-based solutions using equivalent service requirements, workloads, and assumptions. Relevant comparisons include land-based facilities with conventional cooling and water-based cooling, where applicable to the site under study.","Assessment covers energy, capital expenditure, operating costs, maintenance, connectivity, recovery, environmental effects, and end of life. Potential savings in one component do not in themselves demonstrate a lower total cost."]},"placements":{"h2":"Placement alternatives, compared honestly.","intro":["The underlake project is evaluated against three reference placements at equal service: a terrestrial facility, a hardened bunker, and an undersea deployment. Each trade-off below is an initial assessment to be tested, not a measured result.","A companion ten-year cost model at equal service gives 6.00 million dollars for a terrestrial facility with conventional cooling, 6.34 for a hardened terrestrial facility with lake-water cooling, and 7.85 for the submerged design. Submersion buys capability, not cost saving."],"note":"Initial framework assessment for discussion. Figures and rankings require measurement and site studies. Screening thermal numbers (a basin-average anomaly of about 0.001 kelvin over fifty years and a twelve-month footprint of 228-509 metres) carry unproven status until measured.","table":{"rowHeading":"Criterion","columns":[{"icon":"building2","name":"Terrestrial datacenter","sub":"Conventional cooling"},{"icon":"shield-check","name":"Hardened bunker","sub":"Reinforced shell"},{"icon":"waves","name":"Undersea datacenter","sub":"Ocean deployment"},{"icon":"droplets","name":"Underlake datacenter","sub":"Freshwater lake"}],"rows":[{"icon":"history","label":"Operational maturity","values":["Proven operations","Proven for critical workloads","Proven at sea (Project Natick)","Conceptual; unbuilt"]},{"icon":"shield","label":"Physical protection","values":["Site security, exposed perimeter","Reinforced construction, restricted access","Hardened shell, remote siting","Pressure hull, inland water column"]},{"icon":"thermometer","label":"Heat rejection","values":["Mechanical cooling, energy cost","Complex confined heat rejection","Passive water cooling","Passive water cooling, thermal budget unmeasured"]},{"icon":"scale","label":"Jurisdiction","values":["Domestic, urban corridors","Domestic","Contested maritime zones","Domestic inland waters"]},{"icon":"landmark","label":"Land threat surface","values":["Direct perimeter access, site security required","Reinforced against intrusion, restricted access","Remote at sea, shore station remains exposed","Submerged module, shore station remains exposed"]},{"icon":"plane","label":"Air threat surface","values":["Fully exposed from the air","Hardened against aerial threats","Exposed surface support at sea","Module shielded by the water column, shore station exposed"]},{"icon":"anchor","label":"Maritime threat surface","values":["None","None","Submarine cable interception, anchor drag","Out of submarine reach"]},{"icon":"boxes","label":"Scalability","values":["Hyperscale clusters","Harder to scale","Site-limited modules","Lake-limited modules"]},{"icon":"dollar-sign","label":"Ten-year cost model","values":["$6.00M","$6.34M","Not modeled","$7.85M"]},{"icon":"flask-conical","label":"Evidence status","values":["Measured","Measured","Proven pilot","Computed, unproven"]}]}},"scenarios":{"h2":"Use cases under exploration","body":["The project can be evaluated for dedicated computing, storage, or particular infrastructure requirements defined by an organisation. The suitability of each use case must be established through requirements assessment and test evidence.","A use case mentioned here is not a statement that the service is already available or approved to handle sensitive data."],"cta":{"label":"Discuss Technical Requirements","to":"/en/partnerships/#contact"}},"indexLabel":"On this page","index":[{"id":"system","label":"Project architecture"},{"id":"inside","label":"Inside Jalaranu"},{"id":"comparison","label":"Comparing alternatives"},{"id":"placements","label":"Placement comparison"},{"id":"scenarios","label":"Use cases under exploration"}],"inside":{"h2":"Inside Jalaranu","anchor":"inside","intro":["The reference structure breaks the module into 24 numbered components across six systems. The figure is a dimensional engineering draft, not a fabrication drawing."],"items":[{"title":"Protective enclosure","body":"Stainless-steel shell, structural stiffeners, and corrosion protection, carried by a ballast skid. Lifting loads pass through four upper padeyes, while the service lid keeps two seals separated by a monitored interspace."},{"title":"Computing cassette","body":"An 8U cassette holds three 2U servers with SSD/NVMe storage and a network switch, under a proposed nitrogen atmosphere with controlled humidity and A/B power and fibre feedthroughs."},{"title":"Cooling loop","body":"A gas-to-liquid coil and fans move heat into a closed coolant circuit through A/B pumps and A/B external heat exchangers. Isolation valves separate branches, and lake water never mixes with internal coolant."},{"title":"Power resilience","body":"An optional LiFePO4 battery UPS sits in a lower bay separated from the computing equipment, targeting a ten-minute reserve at the assumed 2.1 kW load."},{"title":"Vibration isolation","body":"Four captive isolators with cushioned snubbers suspend the server cassette, with flexible connections, electrical bonding, and transport and service locks."},{"title":"Monitoring and safety","body":"Temperature, humidity, oxygen, pressure, and motion sensors, a camera with window and wiper, and a leak-detection tray feed power distribution and safety controls."}],"note":"All stated values are design assumptions, not measurements. Watertightness, operating depth, lifting capacity, and seismic resistance remain to be established through analysis and integrated testing."}},"validation":{"seoTitle":"Technical, Economic and Environmental Validation | Jalaranu","seoDescription":"Learn about Jalaranu\'s test questions and staged approach to evaluating the feasibility of an underlake datacenter.","hero":{"h1":"Evidence provides the basis for the next step.","body":"The feasibility of an underlake datacenter needs to be assessed **technically, economically, and environmentally**. Jalaranu\'s validation approach focuses on testable questions, explainable methods, and findings presented alongside their limitations."},"status":{"h2":"Development status","items":["The development stage will be announced once it has been confirmed.","The current focus, the latest update, and any evidence approved for sharing will be published as they become available."]},"plan":{"h2":"Questions that shape the test programme.","body":"Success criteria, methods, and responsibilities need to be defined before testing begins.","table":[{"area":"Thermal performance and energy","question":"How does the system perform across defined workloads and environmental conditions?"},{"area":"Structure and integrity","question":"Do the module and its interfaces meet the specified operating and test conditions?"},{"area":"Reliability and recovery","question":"How does the system respond to disruptions, recover, and undergo maintenance?"},{"area":"Whole-life cost","question":"How do installation, operation, intervention, retrieval, and end-of-life costs compare with alternatives?"},{"area":"Environment","question":"How is the baseline documented, change monitored, and the evidence evaluated?"},{"area":"Fitness for use","question":"For which requirements and service levels do test results indicate suitability?"}],"tableHeaderArea":"Area","tableHeaderQuestion":"Evaluation question"},"framework":{"h2":"Staged development, with decisions at each stage.","steps":[{"title":"Requirements definition","body":"Establish objectives, relevant alternatives, and success criteria."},{"title":"Studies and preliminary engineering","body":"Assess candidate sites for further study, risks, system design, and cost assumptions."},{"title":"Component and integration testing","body":"Test the functions that determine system safety and performance."},{"title":"A limited pilot","body":"Measure performance within an agreed scope, supported by monitoring and recovery plans."},{"title":"Evaluation for the next stage","body":"Review findings, limitations, and the feasibility of further development."}],"note":"This sequence is a development framework, not a list of stages claimed to be complete."},"environment":{"h2":"Environmental commitments","body":["Site studies need to consider water conditions, uses of the area, the needs of affected communities, and applicable requirements. The evaluation plan should cover baseline conditions, changes to monitor during testing, and the handling of facilities at end of life.","Study findings inform site and design decisions, including a decision not to proceed with an option if it is unsuitable."],"items":[{"title":"Ecological discipline","body":"The lake is the limiting resource; environmental benefit is never claimed without measurement."},{"title":"A published thermal budget","body":"Screening calculations give a basin-average anomaly of about 0.001 kelvin over fifty years and a twelve-month heat-equivalent footprint of 228-509 metres. Both stay unproven until measured at a candidate site."},{"title":"Baseline before deployment","body":"Baseline conditions, water conditions, area uses, and the needs of affected communities are part of the evaluation plan."},{"title":"End of life","body":"Decommissioning, retrieval, and lake restoration are planned from the start."},{"title":"No-proceed stays valid","body":"Where evidence is insufficient, an option is set aside rather than asserted."}]},"results":{"h2":"Findings and documents","body":"Published findings and documents will appear here once they are available and approved for public release.","cta":{"label":"Discuss the Validation Programme","to":"/en/partnerships/#contact"}},"faq":[{"q":"Is Jalaranu commercially operational?","a":"**This website introduces the Jalaranu project and development opportunities.** Commercial service availability will be communicated separately once facility and service readiness have been confirmed."},{"q":"Why use a lake?","a":"**A lake is the deployment context being explored.** Suitability needs to be assessed against water conditions, access, energy, networking, environmental factors, and intended use. Selecting a lake does not in itself demonstrate an advantage over another location or design."},{"q":"Is the cooling free or energy-free?","a":"**The potential use of the water environment must be assessed alongside heat-transfer systems and the energy requirements of the whole facility.** Jalaranu does not claim specific savings without measured results and a clearly defined comparison."},{"q":"What happens if the module needs repair?","a":"**Monitoring, incident handling, retrieval, and component replacement are part of design evaluation.** Detailed procedures will follow the tested design and agreed service requirements."},{"q":"Can it support sensitive data or defence requirements?","a":"**Suitability needs to be assessed against data classification, system architecture, access controls, governance, and the requirements of the relevant institution.** This website does not claim approval or readiness to handle information at a particular classification level."},{"q":"How are effects on the lake assessed?","a":"**The study approach covers baseline conditions, changes to monitor, and evaluation during testing and at end of life.** Its scope must be adapted to the location and planned activities."},{"q":"How can I obtain more information?","a":"**Use the partnership form to introduce your organisation and the purpose of the discussion.** Information that can be shared will depend on the needs of the discussion and document availability."}],"faqTitle":"Frequently asked questions"},"partnerships":{"seoTitle":"Datacenter Development Partnerships | Jalaranu","seoDescription":"Explore collaboration with Jalaranu as an investor, government or defence institution, industry partner, or research organisation.","hero":{"h1":"Start with the requirement. Agree on what needs to be demonstrated.","body":"Jalaranu welcomes conversations with organisations interested in evaluating, developing, or supporting the underlake datacenter project. Collaboration begins with **clear goals, realistic scope, and measurable results**."},"tracks":[{"id":"investor","h2":"Funding linked to measurable progress.","body":["We invite discussion of market needs, the business model, funding stages, and the evidence required at each stage. The initial focus is to understand how capital can reduce development uncertainty.","Topics include prospective users, available alternatives, cost estimates and their assumptions, capital requirements, and milestones for subsequent investment decisions."],"cta":{"label":"Discuss an Investment Opportunity","formPreset":"investor"}},{"id":"institution","h2":"Evaluate strategic requirements through focused collaboration.","body":["Discussion can begin with infrastructure needs, service continuity, operational control, data governance, and institutional evaluation criteria. The suitability of the Jalaranu project is determined through requirements assessment and relevant testing.","Potential collaboration may include feasibility studies, requirements definition, and the development of a limited pilot. Access requirements, information handling, and each party\'s responsibilities are agreed according to the scope of collaboration."],"cta":{"label":"Explore Institutional Collaboration","formPreset":"institution"}},{"id":"industry","h2":"Connecting engineering, infrastructure, and operational capabilities.","body":["We welcome discussions with prospective partners in energy, connectivity, structures and manufacturing, computing, heat management, sensors, and field operations.","Contributions can be defined around development requirements, interface boundaries, integration responsibilities, and the test outcomes the parties aim to achieve together."],"cta":{"label":"Discuss a Technology Contribution","formPreset":"industry"}},{"id":"research","h2":"Developing methods and evidence that can be reviewed.","body":["Universities and research organisations can explore thermal, structural, reliability, economic, and environmental studies. Research scope, data use, publication, and rights to outcomes need to be agreed from the outset."],"cta":{"label":"Explore Research Collaboration","formPreset":"research"}}],"process":{"h2":"From an initial conversation to a shared scope of work.","steps":["Describe your organisation\'s requirements and objectives.","Discuss fit and the initial information that can be shared.","Define scope, contributions, and evaluation criteria.","Determine the next step based on both parties\' readiness."]},"contact":{"h2":"Tell us what your organisation needs.","body":"Provide brief context and the type of collaboration you would like to explore. Do not include confidential information, credentials, sensitive operational data, or restricted documents in this form.","privacyLink":"Read how your contact information is handled in our Privacy Notice.","helpText":"Sensitive technical details are not needed at this stage.","fields":{"name":"Full name","org":"Organisation name","email":"Contact email","type":"Partnership type","selectPlaceholder":"Select collaboration type","typeOptions":["Investor","Government or defence institution","Industry or technology partner","Research partner","Other"],"message":"Requirements and collaboration objectives","messagePlaceholder":"Describe your requirements, a contribution you could offer, or your initial questions.","submit":"Send Discussion Request"},"success":"Thank you. Your discussion request has been received. The Jalaranu team will review the information you submitted.","error":"Your request has not been sent. Please try again.","unavailable":"The discussion form is not yet active. No data is transmitted from this page. The contact channel will be announced once established.","requiredError":"Please complete this field.","emailError":"Enter a valid email address."}},"about":{"seoTitle":"About Jalaranu | Identity and Development","seoDescription":"Discover Jalaranu\'s identity, development principles, and the people responsible for its underlake datacenter project.","hero":{"h1":"Rooted in Indonesian identity. Developed through evidence.","body":"Jalaranu is an initiative developing an underlake datacenter project. We aim to bring **engineering, infrastructure requirements, and an understanding of the environment** into a measurable development process."},"story":{"h2":"Knowledge, safeguarded.","body":["The name Jalaranu combines “jala”, understood as water in the naming of this brand, and “ranu”, lake. Its visual identity draws inspiration from Javanese heritage.","A guardian goddess supports a datacenter beneath flowing water. The symbol expresses a responsibility to safeguard knowledge and the infrastructure that supports it.","That meaning carries into the way the project is developed: clear questions, focused testing, and honest communication about findings and limitations."]},"principles":{"h2":"Development principles","items":[{"title":"Evidence before scale","body":"Development decisions follow evaluation findings."},{"title":"Responsibility across the facility\'s life","body":"Planning covers installation, operation, recovery, and end of life."},{"title":"Collaboration with clear roles","body":"Contributions, interfaces, and responsibilities are agreed from the outset."},{"title":"Proportionate openness","body":"Public information explains the project rationale; detailed discussion follows need and access authority."}]},"team":{"h2":"Team and organisation","body":"Details about the team, roles, and the accountable entity will be published once they are confirmed and approved for publication.","cta":{"label":"Explore Collaboration Opportunities","to":"/en/partnerships/"}}},"privacy":{"seoTitle":"Privacy | Jalaranu","seoDescription":"The Jalaranu Privacy Notice will explain how contact-form information is handled once the practices are established.","h1":"Privacy Notice","body":["This Privacy Notice will be updated before the contact form is launched. It will explain the operator, the purposes of processing, service providers, retention, and the channel for your data-related requests once the actual practices are established."],"sections":[{"title":"Scope of this notice","body":["This page explains how contact information would be handled once the Jalaranu contact form and related processes are active. The current website is static and does not collect personal data by itself."]},{"title":"Information we plan to collect","body":["When the partnership form becomes active, the information requested will be limited to what is needed to review an enquiry: full name, organisation name, contact email, type of collaboration, and a message describing the organisation\'s needs."]},{"title":"How the information would be used","body":["The information would be used solely to review and respond to partnership enquiries, and to prepare follow-up discussions. It would not be used for marketing without consent and would not be sold to third parties."]},{"title":"Storage, retention and access","body":["Storage location, retention period, access controls, and the responsible data controller will be published here once the form and its processing practices are established. Until then, no form data is processed."]},{"title":"Your rights and contact","body":["Once processing begins, you will be able to request information about your data, corrections, or deletion through the contact channel published on this page. Use the partnership page contact form to reach the team about this notice."]}]},"notFound":{"h1":"Page not found","body":"The page you are looking for does not exist or has moved.","back":"Back to Home","seoTitle":"Page Not Found | Jalaranu","seoDescription":"The page you are looking for could not be found. Return to the Jalaranu website."}},"footer":{"privacy":"Privacy","contact":"Contact","privacyNote":"The Privacy Notice will be updated to reflect actual data-handling practices.","legalHeading":"Legal"},"slugs":{"technology":"technology","validation":"validation","partnerships":"partnerships","about":"about","privacy":"privacy"}}'),r=JSON.parse('{"locale":"id","langLabel":"ID","default":false,"site":{"title":"Jalaranu","tagline":"Proyek datacenter bawah danau","description":"Jelajahi proyek datacenter bawah danau Jalaranu, pendekatan validasi, dan peluang kemitraan untuk pengembangan infrastruktur komputasi di Indonesia.","footerTagline":"Jalaranu - pengembangan proyek datacenter bawah danau untuk ketahanan digital Indonesia. Proyek ini mengevaluasi efisiensi termal, keandalan operasi, dan dampak lingkungan melalui program bertahap berbasis bukti sebelum ada komitmen konstruksi.","copyright":"Jalaranu","logoAlt":"Jalaranu","skipLink":"Langsung ke konten utama","menuToggle":"Buka atau tutup menu","socialFollow":"Ikuti Jalaranu","social":{"instagram":"https://instagram.com/projectjalaranu","x":"https://x.com/projectjalaranu","linkedin":"https://www.linkedin.com/company/projectjalaranu","facebook":"https://www.facebook.com/projectjalaranu","tiktok":"https://www.tiktok.com/@projectjalaranu","github":"https://github.com/jalaranu"},"languageSwitch":"Ganti bahasa ke","languageMenu":"Bahasa","languages":{"en":"English","id":"Bahasa Indonesia"},"carouselPrev":"Slide sebelumnya","carouselNext":"Slide berikutnya","carouselPause":"Jeda tampilan","carouselPlay":"Putar tampilan","carouselGoTo":"Ke slide","carouselSlides":"Slide gambar utama","brandSlogan":"Dingin, sunyi, jagat data lestari."},"nav":{"technology":"Teknologi","validation":"Validasi","partnerships":"Kemitraan","about":"Tentang","primaryCta":"Diskusikan Kemitraan"},"pages":{"home":{"seoTitle":"Jalaranu | Proyek Datacenter Bawah Danau","seoDescription":"Jelajahi proyek datacenter bawah danau Jalaranu, pendekatan validasi, dan peluang kemitraan untuk pengembangan infrastruktur komputasi di Indonesia.","hero":{"eyebrow":"Proyek datacenter bawah danau","h1":"Infrastruktur komputasi **bawah danau** untuk ==ketahanan digital Indonesia==.","intro":["Jalaranu mengembangkan proyek datacenter modular bawah danau. Fokusnya adalah menguji **efisiensi termal, keandalan operasi**, dan kelayakan penerapannya dalam konteks Indonesia.","Kami membuka ruang kolaborasi bagi investor, institusi, dan mitra teknologi untuk membangun dasar pengembangan yang terukur."],"primaryCta":{"label":"Diskusikan Kemitraan","to":"/id/partnerships/#contact"},"secondaryCta":{"label":"Jelajahi Teknologi","to":"/id/technology/"},"caption":"Ilustrasi proyek. Konfigurasi akhir mengikuti hasil studi dan rekayasa.","imageAlt":"Ilustrasi proyek Jalaranu: modul datacenter di bawah permukaan danau yang terhubung ke fasilitas pendukung di darat melalui jalur daya dan komunikasi yang terlindung.","slides":[{"src":"/assets/hero/danau-batur.webp","alt":"Danau Batur, Bali, dilihat dari tepian vulkaniknya"},{"src":"/assets/hero/danau-matano.webp","alt":"Danau Matano, Sulawesi Selatan, danau purba berair dalam"}]},"why":{"h2":"Mengapa mempertimbangkan **bawah danau**?","body":["Penempatan bawah danau menawarkan pendekatan yang berbeda terhadap pengelolaan panas, ruang fisik, dan akses ke infrastruktur. Manfaatnya perlu dinilai bersama konsekuensi pemasangan, pemeliharaan, konektivitas, dan pemulihan.","Pertanyaan utamanya: pada kondisi apa pendekatan ini lebih layak daripada datacenter darat dengan pendinginan berbasis air?","Jalaranu menempatkan perbandingan tersebut sebagai dasar evaluasi."],"focuses":[{"title":"Kinerja termal","body":"**Menilai perpindahan panas** dan kebutuhan energi pada kondisi lokasi dan beban yang ditentukan."},{"title":"Keandalan operasi","body":"**Menguji bagaimana sistem dipantau, dipelihara, dan dipulihkan** ketika terjadi gangguan."},{"title":"Kelayakan menyeluruh","body":"**Membandingkan biaya sepanjang umur fasilitas** serta tanggung jawab terhadap lingkungan."}],"cta":{"label":"Lihat Pendekatan Validasi","to":"/id/validation/"}},"system":{"h2":"Satu sistem, dari darat hingga modul bawah danau.","body":"Proyek Jalaranu menghubungkan fasilitas pendukung di darat dengan modul komputasi di bawah air. Perencanaan mencakup daya, konektivitas, pengelolaan panas, pemantauan, serta cara modul dipasang dan diambil kembali.","items":[{"title":"Fasilitas darat","body":"Antarmuka daya, jaringan, dan pengelolaan operasi."},{"title":"Hubungan darat–modul","body":"Jalur daya dan komunikasi yang perlu dirancang bersama kebutuhan kontinuitas layanan."},{"title":"Modul bawah danau","body":"Wadah komputasi dan sistem pendukung yang akan dievaluasi melalui rekayasa dan pengujian."},{"title":"Pemantauan dan pemulihan","body":"Pengamatan kondisi sistem, penanganan gangguan, dan pengambilan kembali modul."}],"cta":{"label":"Pelajari Proyek","to":"/id/technology/#system"}},"validation":{"h2":"Kemajuan yang dinilai melalui bukti.","body":["Setiap tahap pengembangan perlu menjawab pertanyaan yang spesifik: apakah kinerjanya sesuai kebutuhan, bagaimana sistem berperilaku saat gagal, berapa biaya operasinya, dan bagaimana dampaknya terhadap lingkungan dinilai?","Rencana pengujian, hasil pengukuran, dan keterbatasannya menjadi dasar keputusan untuk melanjutkan pengembangan."],"cta":{"label":"Jelajahi Validasi","to":"/id/validation/"}},"partnerships":{"h2":"Bangun tahap berikutnya bersama Jalaranu.","tracks":[{"title":"Investor","body":"Menjajaki pendanaan berbasis milestone dan evaluasi model bisnis."},{"title":"Pemerintah dan pertahanan","body":"Membahas kebutuhan penggunaan, persyaratan evaluasi, dan kemungkinan pengembangan pilot."},{"title":"Mitra industri","body":"Mengeksplorasi kontribusi pada rekayasa, energi, jaringan, manufaktur, dan operasi."},{"title":"Mitra riset","body":"Menyusun metode pengujian dan kajian teknis, ekonomi, serta lingkungan."}],"cta":{"label":"Temukan Jalur Kemitraan","to":"/id/partnerships/"}},"closing":{"h2":"Apa yang perlu ==dibuktikan agar proyek ini relevan== bagi organisasi Anda?","body":"Mari mulai dari kebutuhan, ruang lingkup evaluasi, dan kontribusi yang dapat dibangun bersama.","cta":{"label":"Diskusikan Kemitraan","to":"/id/partnerships/#contact"}}},"technology":{"seoTitle":"Teknologi Datacenter Bawah Danau | Jalaranu","seoDescription":"Pelajari proyek Jalaranu: dari fasilitas darat dan modul komputasi hingga pengelolaan panas, konektivitas, serta pemulihan.","hero":{"h1":"Rekayasa yang dimulai dari pertanyaan yang tepat.","body":"Jalaranu mengeksplorasi datacenter bawah danau sebagai **satu sistem utuh**. Penempatan modul perlu dievaluasi bersama daya, jaringan, pengelolaan panas, pemeliharaan, dan pemulihannya."},"architecture":{"h2":"Dari antarmuka darat ke lingkungan bawah air.","body":["Arsitektur proyek mencakup empat bagian: fasilitas pendukung darat, jalur daya dan komunikasi, modul komputasi, serta sistem pemantauan dan pengelolaan operasi. Keterkaitan antarbagiannya menentukan bagaimana keseluruhan fasilitas dapat bekerja dan dipulihkan.","Visualisasi awal menggunakan bentuk limas segi empat terpancung. Bentuk tersebut merupakan eksplorasi desain; geometri, material, dan spesifikasi akhir mengikuti hasil rekayasa serta pengujian."],"anchor":"system","visualNote":"Diagram blok dan potongan, dengan jalur logis tanpa koordinat atau rincian pengamanan fasilitas.","imageAlt":"Gambar rekayasa modul limas segi empat terpancung: tampak depan, potongan A-A, denah rangka atap, dan detail sambungan kedap.","imageCaption":"Rancangan rekayasa berdimensi, bukan gambar fabrikasi."},"engineering":{"h2":"Lima bidang yang perlu dievaluasi.","items":[{"title":"Pengelolaan panas","body":"**Kondisi air, perpindahan panas**, beban komputasi, dan energi yang diperlukan sistem pendukung."},{"title":"Integritas modul","body":"**Kemampuan struktur, sambungan, serta antarmuka sistem** menghadapi kondisi operasi yang ditetapkan."},{"title":"Daya dan konektivitas","body":"**Kebutuhan layanan, pilihan redundansi**, perilaku ketika jalur terganggu, dan prosedur pemulihan."},{"title":"Pemeliharaan","body":"**Apa yang dapat dipantau dari jarak jauh**, kapan intervensi diperlukan, serta bagaimana modul ditangani atau diangkat."},{"title":"Keamanan dan kendali","body":"**Akses administratif, pemantauan kejadian, pengelolaan kunci**, tanggung jawab operator, serta perlindungan antarmuka fisik dan digital."}]},"comparison":{"h2":"Keunggulan harus dinilai terhadap alternatif yang relevan.","body":["Evaluasi perlu membandingkan proyek bawah danau dengan solusi darat pada kebutuhan layanan, beban, dan asumsi yang setara. Perbandingan mencakup fasilitas darat dengan pendinginan konvensional maupun pendinginan berbasis air, bila relevan untuk lokasi yang dikaji.","Aspek penilaian meliputi energi, biaya investasi, biaya operasi, pemeliharaan, konektivitas, pemulihan, dampak lingkungan, dan akhir masa pakai. Potensi penghematan pada satu komponen tidak dengan sendirinya menunjukkan biaya total yang lebih rendah."]},"placements":{"h2":"Alternatif penempatan, dibandingkan dengan jujur.","intro":["Proyek bawah danau dievaluasi terhadap tiga penempatan acuan pada tingkat layanan yang setara: fasilitas darat, bunker yang diperkuat, dan penempatan bawah laut. Setiap pertukaran di bawah ini adalah penilaian awal untuk diuji, bukan hasil pengukuran.","Model biaya sepuluh tahun pendamping pada tingkat layanan setara memberi 6,00 juta dolar untuk fasilitas darat dengan pendinginan konvensional, 6,34 untuk fasilitas darat yang diperkeras dengan pendinginan air danau, dan 7,85 untuk desain terendam. Submersion membeli kemampuan, bukan penghematan biaya."],"note":"Penilaian kerangka awal untuk diskusi. Angka dan peringkat memerlukan pengukuran serta kajian lokasi. Angka termal penyaringan (anomali rata-rata cekungan sekitar 0,001 kelvin selama lima puluh tahun dan jejak dua belas bulan 228-509 meter) berstatus belum terbukti sampai diukur.","table":{"rowHeading":"Kriteria","columns":[{"icon":"building2","name":"Datacenter darat","sub":"Pendinginan konvensional"},{"icon":"shield-check","name":"Bunker diperkuat","sub":"Cangkang berpelindung"},{"icon":"waves","name":"Datacenter bawah laut","sub":"Penempatan laut"},{"icon":"droplets","name":"Datacenter bawah danau","sub":"Danau air tawar"}],"rows":[{"icon":"history","label":"Kematangan operasi","values":["Terbukti beroperasi","Terbukti untuk beban kritis","Terbukti di laut (Project Natick)","Konseptual; belum dibangun"]},{"icon":"shield","label":"Perlindungan fisik","values":["Keamanan tapak, perimeter terbuka","Konstruksi diperkuat, akses terbatas","Cangkang diperkeras, lokasi jauh","Lambung tekan, kolom air daratan"]},{"icon":"thermometer","label":"Pembuangan panas","values":["Pendinginan mekanis, biaya energi","Pembuangan panas ruang tertutup yang rumit","Pendinginan air pasif","Pendinginan air pasif, anggaran termal belum diukur"]},{"icon":"scale","label":"Yurisdiksi","values":["Domestik, koridor perkotaan","Domestik","Zona maritim yang diperebutkan","Perairan daratan domestik"]},{"icon":"landmark","label":"Permukaan ancaman darat","values":["Akses perimeter langsung, keamanan tapak diperlukan","Diperkuat terhadap intrusi, akses terbatas","Jauh di laut, stasiun darat tetap terpapar","Modul terendam, stasiun darat tetap terpapar"]},{"icon":"plane","label":"Permukaan ancaman udara","values":["Terpapar penuh dari udara","Diperkeras terhadap ancaman udara","Dukungan permukaan terpapar di laut","Modul terlindung kolom air, stasiun darat terpapar"]},{"icon":"anchor","label":"Permukaan ancaman maritim","values":["Tidak ada","Tidak ada","Penyadapan kabel kapal selam, seret jangkar","Di luar jangkauan kapal selam"]},{"icon":"boxes","label":"Skalabilitas","values":["Klaster hiperskala","Lebih sulit diskalakan","Modul terbatas lokasi","Modul terbatas danau"]},{"icon":"dollar-sign","label":"Model biaya sepuluh tahun","values":["$6,00 juta","$6,34 juta","Belum dimodelkan","$7,85 juta"]},{"icon":"flask-conical","label":"Status bukti","values":["Terukur","Terukur","Pilot terbukti","Dihitung, belum terbukti"]}]}},"scenarios":{"h2":"Skenario penggunaan yang dieksplorasi","body":["Proyek ini dapat dievaluasi untuk komputasi khusus, penyimpanan, atau kebutuhan infrastruktur tertentu berdasarkan persyaratan organisasi. Kesesuaian setiap skenario harus ditentukan melalui evaluasi kebutuhan dan bukti pengujian.","Penyebutan skenario penggunaan bukan pernyataan bahwa layanan tersebut sudah tersedia atau telah disetujui untuk menangani data sensitif."],"cta":{"label":"Bahas Kebutuhan Teknis","to":"/id/partnerships/#contact"}},"indexLabel":"Di halaman ini","index":[{"id":"system","label":"Arsitektur proyek"},{"id":"inside","label":"Di Dalam Jalaranu"},{"id":"comparison","label":"Membandingkan alternatif"},{"id":"placements","label":"Perbandingan penempatan"},{"id":"scenarios","label":"Skenario penggunaan"}],"inside":{"h2":"Di Dalam Jalaranu","anchor":"inside","intro":["Struktur acuan memecah modul menjadi 24 komponen bernomor dalam enam sistem. Figur ini adalah rancangan rekayasa berdimensi, bukan gambar fabrikasi."],"items":[{"title":"Selubung pelindung","body":"Cangkang baja tahan karat, pengaku struktural, dan pelindung antikorosi yang ditopang skid ballast. Beban pengangkatan melewati empat padeye atas, sementara tutup servis menjaga dua seal yang dipisahkan ruang antar-seal terpantau."},{"title":"Kaset komputasi","body":"Kaset 8U menampung tiga server 2U dengan penyimpanan SSD/NVMe dan switch jaringan, di bawah usulan atmosfer nitrogen dengan kelembapan terkendali serta penetrator daya A/B dan serat optik."},{"title":"Sirkuit pendinginan","body":"Coil gas-cairan dan kipas memindahkan panas ke sirkuit coolant tertutup melalui pompa A/B dan penukar panas eksternal A/B. Katup isolasi memisahkan cabang, dan air danau tidak pernah bercampur dengan coolant internal."},{"title":"Ketahanan daya","body":"UPS baterai LiFePO4 opsional ditempatkan di ruang bawah yang terpisah dari perangkat komputasi, dengan target cadangan sepuluh menit pada beban asumsi 2,1 kW."},{"title":"Isolasi getaran","body":"Empat isolator captive dengan snubber berperedam menopang kaset server, dengan sambungan fleksibel, bonding listrik, serta pengunci transportasi dan servis."},{"title":"Pemantauan dan keselamatan","body":"Sensor temperatur, kelembapan, oksigen, tekanan, dan gerak, kamera dengan jendela dan wiper, serta tray pendeteksi kebocoran memberi masukan bagi distribusi daya dan kontrol keselamatan."}],"note":"Seluruh nilai adalah asumsi desain, bukan hasil pengukuran. Kedap air, kedalaman operasi, kapasitas angkat, dan ketahanan gempa harus ditetapkan melalui analisis dan pengujian rakitan terintegrasi."}},"validation":{"seoTitle":"Validasi Teknis, Ekonomi, dan Lingkungan | Jalaranu","seoDescription":"Kenali pertanyaan pengujian dan pendekatan evaluasi Jalaranu untuk menilai kelayakan datacenter bawah danau secara bertahap.","hero":{"h1":"Bukti menjadi dasar untuk melangkah.","body":"Kelayakan datacenter bawah danau perlu dinilai secara **teknis, ekonomi, dan lingkungan**. Pendekatan validasi Jalaranu berfokus pada pertanyaan yang dapat diuji, metode yang dapat dijelaskan, serta hasil yang disampaikan bersama batasannya."},"status":{"h2":"Status pengembangan","items":["Tahap pengembangan akan diumumkan setelah dikonfirmasi.","Fokus pekerjaan, tanggal pembaruan, dan bukti yang dapat dibagikan akan disampaikan setelah tersedia."]},"plan":{"h2":"Pertanyaan yang membentuk rencana pengujian.","body":"Kriteria keberhasilan, metode, dan tanggung jawab perlu ditetapkan sebelum pengujian dimulai.","table":[{"area":"Termal dan energi","question":"Bagaimana sistem bekerja pada rentang beban dan kondisi lingkungan yang ditetapkan?"},{"area":"Struktur dan integritas","question":"Apakah modul serta antarmukanya memenuhi kondisi operasi dan pengujian yang ditentukan?"},{"area":"Keandalan dan pemulihan","question":"Bagaimana sistem merespons gangguan, dipulihkan, dan dipelihara?"},{"area":"Biaya sepanjang umur fasilitas","question":"Bagaimana biaya pemasangan, operasi, intervensi, pengambilan kembali, dan akhir masa pakai dibanding alternatif?"},{"area":"Lingkungan","question":"Bagaimana kondisi awal didokumentasikan, perubahan dipantau, dan hasilnya dievaluasi?"},{"area":"Kesesuaian penggunaan","question":"Untuk kebutuhan dan tingkat layanan apa hasil pengujian menunjukkan kecocokan?"}],"tableHeaderArea":"Bidang","tableHeaderQuestion":"Pertanyaan evaluasi"},"framework":{"h2":"Pengembangan bertahap, dengan keputusan pada setiap tahap.","steps":[{"title":"Perumusan kebutuhan","body":"Menetapkan tujuan, alternatif pembanding, dan kriteria keberhasilan."},{"title":"Studi dan rekayasa awal","body":"Menilai lokasi yang layak dikaji, risiko, rancangan sistem, serta asumsi biaya."},{"title":"Pengujian komponen dan integrasi","body":"Menguji fungsi yang menentukan keselamatan dan kinerja sistem."},{"title":"Pilot terbatas","body":"Mengukur kinerja pada lingkup yang disepakati, dengan rencana pemantauan dan pemulihan."},{"title":"Evaluasi untuk tahap berikutnya","body":"Menilai hasil, kekurangan, dan kelayakan pengembangan lebih lanjut."}],"note":"Urutan ini adalah kerangka pengembangan, bukan daftar tahap yang dinyatakan telah selesai."},"environment":{"h2":"Komitmen lingkungan","body":["Kajian lokasi perlu mempertimbangkan kondisi perairan, penggunaan kawasan, kebutuhan masyarakat terkait, serta persyaratan yang berlaku. Rencana evaluasi harus mencakup kondisi awal, perubahan yang dipantau selama pengujian, dan penanganan fasilitas pada akhir masa pakai.","Hasil kajian menjadi masukan untuk keputusan lokasi dan desain, termasuk keputusan untuk tidak melanjutkan suatu opsi bila tidak layak."],"items":[{"title":"Disiplin ekologis","body":"Danau adalah sumber daya pembatas; manfaat lingkungan tidak pernah diklaim tanpa pengukuran."},{"title":"Anggaran termal yang dipublikasikan","body":"Perhitungan penyaringan memberi anomali rata-rata cekungan sekitar 0,001 kelvin selama lima puluh tahun dan jejak setara panas dua belas bulan 228-509 meter. Keduanya berstatus belum terbukti sampai diukur di lokasi kandidat."},{"title":"Baseline sebelum penempatan","body":"Kondisi awal, kondisi air, penggunaan kawasan, dan kebutuhan masyarakat terdampak menjadi bagian dari rencana evaluasi."},{"title":"Akhir masa pakai","body":"Pengakhiran, pengambilan kembali, dan pemulihan danau direncanakan sejak awal."},{"title":"Tidak melanjutkan tetap sah","body":"Jika bukti tidak mencukupi, opsi disingkirkan alih-alih dipaksakan."}]},"results":{"h2":"Ringkasan hasil dan dokumen","body":"Dokumen dan hasil yang dapat dibagikan akan ditampilkan setelah tersedia dan disetujui untuk publikasi.","cta":{"label":"Diskusikan Program Validasi","to":"/id/partnerships/#contact"}},"faq":[{"q":"Apakah Jalaranu sudah beroperasi secara komersial?","a":"**Website ini memperkenalkan proyek dan peluang pengembangan Jalaranu.** Ketersediaan layanan komersial akan disampaikan secara terpisah setelah kesiapan fasilitas dan layanannya dikonfirmasi."},{"q":"Mengapa menggunakan danau?","a":"**Danau merupakan konteks penempatan yang sedang dieksplorasi.** Kesesuaiannya perlu dinilai berdasarkan kondisi perairan, akses, energi, jaringan, lingkungan, dan kebutuhan penggunaan. Pemilihan danau tidak dengan sendirinya membuktikan keunggulan terhadap lokasi atau desain lain."},{"q":"Apakah pendinginannya gratis atau tanpa energi?","a":"**Potensi pemanfaatan lingkungan perairan harus dinilai bersama sistem perpindahan panas dan kebutuhan energi seluruh fasilitas.** Jalaranu belum menyatakan penghematan tertentu tanpa hasil pengukuran dan pembanding yang jelas."},{"q":"Bagaimana jika modul memerlukan perbaikan?","a":"**Kemampuan pemantauan, penanganan gangguan, pengambilan kembali, dan penggantian komponen merupakan bagian dari evaluasi desain.** Prosedur rinci akan mengikuti rancangan yang telah diuji serta kebutuhan layanan yang disepakati."},{"q":"Apakah dapat digunakan untuk data sensitif atau kebutuhan pertahanan?","a":"**Kesesuaian penggunaan perlu dievaluasi berdasarkan klasifikasi data, arsitektur sistem, kontrol akses, tata kelola, dan persyaratan institusi terkait.** Website ini tidak menyatakan persetujuan atau kesiapan untuk menangani informasi dengan klasifikasi tertentu."},{"q":"Bagaimana dampak terhadap danau dinilai?","a":"**Pendekatan kajian mencakup kondisi awal, perubahan yang perlu dipantau, serta evaluasi selama pengujian dan pada akhir masa pakai.** Ruang lingkupnya harus disesuaikan dengan lokasi dan kegiatan yang direncanakan."},{"q":"Bagaimana memperoleh informasi lebih lanjut?","a":"**Gunakan formulir kemitraan untuk menjelaskan organisasi dan tujuan diskusi.** Informasi yang dapat dibagikan akan ditentukan berdasarkan kebutuhan pembahasan dan ketersediaan dokumen."}],"faqTitle":"Pertanyaan yang sering diajukan"},"partnerships":{"seoTitle":"Kemitraan Pengembangan Datacenter | Jalaranu","seoDescription":"Jajaki kerja sama bersama Jalaranu sebagai investor, institusi pemerintah atau pertahanan, mitra industri, maupun mitra riset.","hero":{"h1":"Mulai dari kebutuhan. Sepakati apa yang perlu dibuktikan.","body":"Jalaranu membuka percakapan dengan pihak yang ingin menilai, mengembangkan, atau mendukung proyek datacenter bawah danau. Kerja sama dimulai dengan **tujuan yang jelas, lingkup yang realistis, hasil yang dapat dievaluasi**."},"tracks":[{"id":"investor","h2":"Pendanaan yang dikaitkan dengan kemajuan terukur.","body":["Kami mengundang pembahasan tentang kebutuhan pasar, model bisnis, tahapan pendanaan, dan bukti yang perlu dihasilkan pada setiap tahap. Fokus awalnya adalah memahami bagaimana modal dapat digunakan untuk mengurangi ketidakpastian pengembangan.","Ruang pembahasan mencakup calon pengguna, alternatif yang tersedia, estimasi biaya beserta asumsi, kebutuhan modal, serta milestone untuk keputusan investasi berikutnya."],"cta":{"label":"Bahas Peluang Investasi","formPreset":"investor"}},{"id":"institution","h2":"Evaluasi kebutuhan strategis melalui kerja sama yang terarah.","body":["Pembahasan dapat dimulai dari kebutuhan infrastruktur, kontinuitas layanan, kendali operasional, tata kelola data, dan kriteria evaluasi institusi. Kesesuaian proyek Jalaranu ditentukan melalui kajian kebutuhan dan pengujian yang relevan.","Kemungkinan ruang kerja sama mencakup studi kelayakan, penyusunan kebutuhan, dan pengembangan pilot terbatas. Persyaratan akses, penanganan informasi, serta tanggung jawab masing-masing pihak disepakati sesuai lingkup kerja sama."],"cta":{"label":"Jajaki Kerja Sama Institusi","formPreset":"institution"}},{"id":"industry","h2":"Menghubungkan kemampuan rekayasa, infrastruktur, dan operasi.","body":["Kami membuka pembahasan dengan calon mitra di bidang energi, konektivitas, struktur dan manufaktur, komputasi, pengelolaan panas, sensor, serta operasi lapangan.","Kontribusi dapat dibahas berdasarkan kebutuhan pengembangan, batas antarmuka, tanggung jawab integrasi, serta hasil pengujian yang ingin dicapai bersama."],"cta":{"label":"Bahas Kontribusi Teknologi","formPreset":"industry"}},{"id":"research","h2":"Mengembangkan metode dan bukti yang dapat ditinjau.","body":["Perguruan tinggi dan lembaga riset dapat menjajaki kajian termal, struktur, keandalan, ekonomi, serta lingkungan. Ruang lingkup penelitian, penggunaan data, publikasi, dan hak atas hasil perlu disepakati sejak awal."],"cta":{"label":"Jajaki Kolaborasi Riset","formPreset":"research"}}],"process":{"h2":"Dari percakapan awal ke lingkup kerja bersama.","steps":["Sampaikan kebutuhan dan tujuan organisasi Anda.","Bahas kesesuaian serta informasi awal yang dapat dibagikan.","Rumuskan ruang lingkup, kontribusi, dan kriteria evaluasi.","Tentukan langkah berikutnya berdasarkan kesiapan kedua pihak."]},"contact":{"h2":"Ceritakan kebutuhan organisasi Anda.","body":"Sampaikan konteks singkat dan bentuk kerja sama yang ingin dijajaki. Jangan menyertakan informasi rahasia, kredensial, data operasional sensitif, atau dokumen terbatas dalam formulir ini.","privacyLink":"Pelajari pengelolaan data kontak Anda dalam Pemberitahuan Privasi.","helpText":"Tidak perlu menyertakan rincian teknis sensitif pada tahap awal.","fields":{"name":"Nama lengkap","org":"Nama organisasi","email":"Email yang dapat dihubungi","type":"Jenis kerja sama","selectPlaceholder":"Pilih jenis kerja sama","typeOptions":["Investor","Pemerintah atau institusi pertahanan","Mitra industri atau teknologi","Mitra riset","Lainnya"],"message":"Kebutuhan dan tujuan kerja sama","messagePlaceholder":"Jelaskan kebutuhan, kontribusi yang dapat ditawarkan, atau pertanyaan awal Anda.","submit":"Kirim Permintaan Diskusi"},"success":"Terima kasih. Permintaan diskusi Anda telah diterima. Tim Jalaranu akan meninjau informasi yang Anda kirimkan.","error":"Permintaan belum terkirim. Silakan coba lagi.","unavailable":"Formulir diskusi belum aktif. Tidak ada data yang dikirimkan dari halaman ini. Kanal kontak akan diumumkan setelah tersedia.","requiredError":"Lengkapi kolom ini.","emailError":"Masukkan alamat email yang valid."}},"about":{"seoTitle":"Tentang Jalaranu | Identitas dan Pengembangan","seoDescription":"Kenali Jalaranu, cerita identitasnya, prinsip pengembangan, dan pihak yang bertanggung jawab atas proyek datacenter bawah danau.","hero":{"h1":"Berakar pada identitas Indonesia. Dibangun melalui pembuktian.","body":"Jalaranu adalah inisiatif pengembangan proyek datacenter bawah danau. Kami ingin mempertemukan **rekayasa, kebutuhan infrastruktur, serta pemahaman terhadap lingkungan** dalam satu proses pengembangan yang terukur."},"story":{"h2":"Pengetahuan yang dijaga.","body":["Nama Jalaranu menggabungkan “jala”, yang dimaknai sebagai air dalam penamaan brand ini, dan “ranu”, danau. Identitasnya mengambil inspirasi visual dari warisan Jawa.","Sosok dewi penjaga menyangga bentuk datacenter di bawah gelombang air. Simbol ini menyampaikan tanggung jawab untuk menjaga pengetahuan dan infrastruktur yang menopangnya.","Makna tersebut diterjemahkan dalam cara proyek dikembangkan: pertanyaan yang jelas, pengujian yang terarah, dan komunikasi yang jujur tentang hasil serta keterbatasannya."]},"principles":{"h2":"Prinsip pengembangan","items":[{"title":"Bukti sebelum skala","body":"Keputusan pengembangan mengikuti hasil evaluasi."},{"title":"Tanggung jawab sepanjang umur fasilitas","body":"Perencanaan mencakup pemasangan, operasi, pemulihan, serta akhir masa pakai."},{"title":"Kolaborasi dengan peran yang jelas","body":"Kontribusi, antarmuka, dan tanggung jawab disepakati sejak awal."},{"title":"Keterbukaan yang proporsional","body":"Informasi publik menjelaskan dasar proyek; pembahasan terperinci mengikuti kebutuhan dan kewenangan akses."}]},"team":{"h2":"Tim dan organisasi","body":"Informasi mengenai tim, peran, dan badan usaha penanggung jawab akan ditampilkan setelah dikonfirmasi dan disetujui untuk publikasi.","cta":{"label":"Kenali Peluang Kolaborasi","to":"/id/partnerships/"}}},"privacy":{"seoTitle":"Privasi | Jalaranu","seoDescription":"Pemberitahuan Privasi Jalaranu akan menjelaskan pengelolaan data formulir kontak setelah praktiknya ditetapkan.","h1":"Pemberitahuan Privasi","body":["Pemberitahuan Privasi ini akan diperbarui sebelum formulir kontak diluncurkan. Halaman ini akan menjelaskan pengelola data, tujuan pemrosesan, penyedia layanan, retensi, serta kanal permintaan terkait data Anda setelah praktiknya ditetapkan."],"sections":[{"title":"Ruang lingkup pemberitahuan ini","body":["Halaman ini menjelaskan cara informasi kontak akan dikelola setelah formulir kontak Jalaranu dan proses terkaitnya aktif. Saat ini situs bersifat statis dan tidak mengumpulkan data pribadi dengan sendirinya."]},{"title":"Informasi yang direncanakan untuk dikumpulkan","body":["Ketika formulir kemitraan aktif, informasi yang diminta akan dibatasi pada hal yang diperlukan untuk meninjau permintaan: nama lengkap, nama organisasi, email yang dapat dihubungi, jenis kerja sama, dan pesan yang menjelaskan kebutuhan organisasi."]},{"title":"Cara informasi akan digunakan","body":["Informasi akan digunakan semata-mata untuk meninjau dan menanggapi permintaan kemitraan serta menyiapkan pembahasan lanjutan. Informasi tidak akan digunakan untuk pemasaran tanpa persetujuan dan tidak akan dijual kepada pihak ketiga."]},{"title":"Penyimpanan, retensi, dan akses","body":["Lokasi penyimpanan, masa retensi, kontrol akses, dan penanggung jawab data akan dipublikasikan di halaman ini setelah formulir dan praktik pemrosesannya ditetapkan. Sebelum itu, tidak ada data formulir yang diproses."]},{"title":"Hak Anda dan kontak","body":["Setelah pemrosesan dimulai, Anda dapat meminta informasi tentang data Anda, perbaikan, atau penghapusan melalui kanal kontak yang dipublikasikan di halaman ini. Gunakan formulir kontak pada halaman kemitraan untuk menghubungi tim terkait pemberitahuan ini."]}]},"notFound":{"h1":"Halaman tidak ditemukan","body":"Halaman yang Anda cari tidak tersedia atau telah dipindahkan.","back":"Kembali ke Beranda","seoTitle":"Halaman Tidak Ditemukan | Jalaranu","seoDescription":"Halaman yang Anda cari tidak dapat ditemukan. Kembali ke situs Jalaranu."}},"footer":{"privacy":"Privasi","contact":"Kontak","privacyNote":"Pemberitahuan Privasi akan diperbarui mengikuti praktik pengelolaan data yang berlaku.","legalHeading":"Hukum"},"slugs":{"technology":"technology","validation":"validation","partnerships":"partnerships","about":"about","privacy":"privacy"}}'),o=n(1396);const l={en:s,id:r},d=n.n(o)().siteMetadata.siteUrl,u=a=>"/id"===a||a.startsWith("/id/")?"id":"en",p=(a,e)=>{const n="en"===e?"id":"en";return a===`/${e}`||a.startsWith(`/${e}/`)?a.replace(`/${e}`,`/${n}`):`/${n}/`};function m(){const{0:a,1:e}=(0,i.useState)({locale:"en",currentPath:"/en/404/"});(0,i.useEffect)(()=>{const a=window.location.pathname,n=u(a);e({locale:n,currentPath:a})},[]);const n=l[a.locale],s={locale:a.locale,pageKey:"notFound",content:n,currentPath:a.currentPath,equivalentPath:p(a.currentPath,a.locale),siteUrl:d};return i.createElement(t.default,{pageContext:s})}function c({location:a}){const e=u(a.pathname),n=l[e].pages.notFound;return i.createElement(i.Fragment,null,i.createElement("html",{lang:e}),i.createElement("title",null,n.seoTitle),i.createElement("meta",{name:"description",content:n.seoDescription}),i.createElement("meta",{name:"robots",content:"noindex,follow"}))}}}]);
